import os
os.environ["POLARS_MAX_THREADS"]="2"
os.environ["POLARS_UNKNOWN_EXTENSION_TYPE_BEHAVIOR"]="load_as_storage"
import polars as pl, glob
pl.Config.set_tbl_rows(100); pl.Config.set_tbl_cols(40); pl.Config.set_tbl_width_chars(300)
B="/home/user/prc-data-challenge/"; R=B+"data/raw/"
rank=pl.scan_parquet(R+"ranking.parquet"); tr=pl.scan_parquet(sorted(glob.glob(R+"training_*.parquet")))
sec=lambda a,b:(pl.col(a)-pl.col(b)).dt.total_seconds()
dep=tr.filter(pl.col("PHASE_mvt")=="DEP").with_columns([pl.col("FLIGHT_ID_mvt").is_null().alias("unm"),sec("MVT_TIME_UTC_mvt","SCHED_TIME_UTC_mvt").alias("ms"),(sec("BLOCK_TIME_UTC_mvt","SCHED_TIME_UTC_mvt").abs()<=10).alias("fill"),sec("MVT_TIME_UTC_mvt","AOBT_3_flt").alias("proxy"),sec("AOBT_3_flt","SCHED_TIUE_UTC_mvt".replace("TIUE","TIME")).alias("as_"),pl.col("TAXITIME_SEC_mvt").alias("y")]).collect()
oof=pl.read_parquet(sorted(glob.glob(B+"experiments/oof_main-*.parquet"),key=os.path.getmtime)[-1]).drop_nulls("oof")
j=dep.join(oof,on="MVT_ID_mvt").with_columns(((pl.col("y")-pl.col("oof"))**2).alias("se"))
tot=j["se"].sum(); print("OOF rows",j.height,"rmse",(tot/j.height)**0.5)
print("=== N. OOF SSE share of specific mechanisms ===")
def share(mask,name):
    s=j.filter(mask); print(f"{name:60s} n={s.height:7d} sse_share={s['se'].sum()/tot:.3f} rmse_in={((s['se'].mean())**0.5 if s.height else float('nan')):.0f} pred_med={s['oof'].median()} y_med={s['y'].median()}")
share(pl.col("unm")&(pl.col("ADEP_mvt")=="LIRF")&(pl.col("ms")>=7200),"LIRF unmatched, mvt-sched>=2h")
share(pl.col("unm")&(pl.col("ADEP_mvt")=="LIRF")&(pl.col("ms")>=7200)&pl.col("fill"),"  of which BLOCK filled (y=mvt-sched)")
share(pl.col("unm")&(pl.col("ADEP_mvt")=="LIRF")&(pl.col("ms")>=7200)&~pl.col("fill"),"  of which real BLOCK (normal y)")
share(pl.col("unm")&(pl.col("ADEP_mvt")!="LIRF")&(pl.col("ms")>=7200),"non-LIRF unmatched, mvt-sched>=2h")
share(pl.col("unm")&(pl.col("ms")<7200),"unmatched, mvt-sched<2h")
share((~pl.col("unm"))&(pl.col("ADEP_mvt")=="LIRF")&pl.col("fill")&(pl.col("as_").abs()>600),"LIRF matched, BLOCK filled & AOBT far from sched")
share((~pl.col("unm"))&(pl.col("ADEP_mvt")=="LIRF"),"LIRF matched all")
share((~pl.col("unm"))&(pl.col("ADEP_mvt")!="LIRF"),"non-LIRF matched all")
share((~pl.col("unm"))&((pl.col("proxy")-pl.col("y")).abs()>3600),"matched, |proxy-y|>1h")
share((pl.col("y")>=72000),"y>=20h (day rollover)")
share((pl.col("oof")>=7200)&(pl.col("y")<3600),"false alarms pred>=2h, y<1h")
print("=== N2. per-airport OOF: unmatched rmse and sse share ===")
print(j.group_by(["ADEP_mvt","unm"]).agg([pl.len(),(pl.col("se").mean()**0.5).round(0).alias("rmse"),(pl.col("se").sum()/tot).round(3).alias("sse_share")]).sort(["unm","sse_share"],descending=[False,True]))
print("=== O. LIRF unmatched, ms>=2h: is 'fill' separable by visible columns? ===")
l=dep.filter(pl.col("unm")&(pl.col("ADEP_mvt")=="LIRF")&(pl.col("ms")>=7200))
print("n",l.height,"fill rate",l["fill"].mean())
for c in ["FLIGHT_RULE_mvt","RUNWAY_mvt"]:
    print(l.group_by(c).agg([pl.len(),pl.col("fill").mean().round(2)]).sort("len",descending=True).head(8))
print(l.with_columns(pl.col("AIRCRAFT_TYPE_mvt").is_null().alias("type_null")).group_by("type_null").agg([pl.len(),pl.col("fill").mean().round(2)]))
print(l.with_columns((pl.col("ms")//3600).alias("ms_h")).group_by("ms_h").agg([pl.len(),pl.col("fill").mean().round(2)]).sort("ms_h"))
print(l.with_columns(pl.col("MVT_TIME_UTC_mvt").dt.hour().alias("h")).group_by("h").agg([pl.len(),pl.col("fill").mean().round(2)]).sort("h").transpose(include_header=True))
print(l.with_columns((pl.col("SCHED_TIME_UTC_mvt").dt.date()!=pl.col("MVT_TIME_UTC_mvt").dt.date()).alias("crosses_midnight")).group_by("crosses_midnight").agg([pl.len(),pl.col("fill").mean().round(2)]))
md=dep.filter(~pl.col("unm"))
print(l.with_columns(pl.col("FLIGHT_mvt").is_in(md["FLIGHT_mvt"].implode()).alias("seen_matched")).group_by("seen_matched").agg([pl.len(),pl.col("fill").mean().round(2)]))
print(l.with_columns(pl.col("FLIGHT_mvt").str.slice(0,3).alias("p3")).group_by("p3").agg([pl.len(),pl.col("fill").mean().round(2)]).filter(pl.col("len")>=10).sort("len",descending=True))
print("=== P. what main.parquet predicts for ranking LIRF unmatched ms>=2h, and EHAM Jan unmatched ===")
main=pl.read_parquet(B+"outputs/main.parquet").rename({"TAXITIME_SEC_mvt":"pred"})
rk=rank.filter(pl.col("PHASE_mvt")=="DEP").with_columns([pl.col("FLIGHT_ID_mvt").is_null().alias("unm"),sec("MVT_TIME_UTC_mvt","SCHED_TIME_UTC_mvt").alias("ms")]).collect().join(main,on="MVT_ID_mvt")
s=rk.filter(pl.col("unm")&(pl.col("ADEP_mvt")=="LIRF")&(pl.col("ms")>=7200))
print("ranking LIRF unm ms>=2h: n",s.height,"pred quantiles",s["pred"].quantile(0.1),s["pred"].median(),s["pred"].quantile(0.9),"ms median",s["ms"].median(),"n pred>=2h",(s["pred"]>=7200).sum())
s2=rk.filter(pl.col("unm")&(pl.col("ADEP_mvt")=="EHAM")&(pl.col("MVT_TIME_UTC_mvt").dt.month()==1))
print("ranking EHAM Jan unmatched: n",s2.height,"pred median",s2["pred"].median(),"p90",s2["pred"].quantile(0.9))
print("training EHAM unmatched label by Jan day-type (disruption days 5,18 vs others):")
e=dep.filter(pl.col("unm")&(pl.col("ADEP_mvt")=="EHAM")&(pl.col("MVT_TIME_UTC_mvt").dt.month()==1)).with_columns(pl.col("MVT_TIME_UTC_mvt").dt.day().is_in([5,18]).alias("disruption"))
print(e.group_by("disruption").agg([pl.len(),pl.col("y").median(),pl.col("y").quantile(0.9).alias("p90"),pl.col("y").std().alias("sd")]))
print("training EHAM matched, Jan: y by disruption day vs others")
em=dep.filter((~pl.col("unm"))&(pl.col("ADEP_mvt")=="EHAM")&(pl.col("MVT_TIME_UTC_mvt").dt.month()==1)).with_columns(pl.col("MVT_TIME_UTC_mvt").dt.day().is_in([5,18]).alias("disruption"))
print(em.group_by("disruption").agg([pl.len(),pl.col("y").median(),pl.col("y").quantile(0.9).alias("p90"),(pl.col("y")-pl.col("proxy")).std().alias("resid_sd")]))
print("=== Q. ranking: rows per airport with ms>=2h by matched (where tail predictions can land) ===")
print(rk.filter(pl.col("ms")>=7200).group_by(["ADEP_mvt","unm"]).agg([pl.len(),(pl.col("pred")>=7200).sum().alias("n_pred_ge2h"),pl.col("pred").median().alias("pred_med")]).sort(["unm","ADEP_mvt"]))
